practice.solution:
import math
def rlhf_objective(pi, pi_ref, rewards, beta):
    er = 0.0
    kl = 0.0
    for p, q, r in zip(pi, pi_ref, rewards):
        er += p * r
        if p > 0:
            kl += p * math.log(p / q)
    return round(er - beta * kl, 9)

